<?php
namespace App\Events;
use App\Models\ChatMessage;use Illuminate\Broadcasting\PrivateChannel;use Illuminate\Contracts\Broadcasting\ShouldBroadcastNow;use Illuminate\Foundation\Events\Dispatchable;use Illuminate\Queue\SerializesModels;
/** Provides chat message changed behavior within the WorkIntel application. */ class ChatMessageChanged implements ShouldBroadcastNow{use Dispatchable,SerializesModels;/** Initializes the class with its required dependencies and state. */ public function __construct(public ChatMessage $message,public string $action='created'){}/** Handles the broadcast on operation for the current WorkIntel workflow. */ public function broadcastOn():array{return[new PrivateChannel('workspace.'.$this->message->workspace_id.'.chat.'.$this->message->conversation_id)];}/** Handles the broadcast as operation for the current WorkIntel workflow. */ public function broadcastAs():string{return'chat.message.'.$this->action;}/** Handles the broadcast with operation for the current WorkIntel workflow. */ public function broadcastWith():array{return['message_id'=>$this->message->id,'conversation_id'=>$this->message->conversation_id,'action'=>$this->action];}}
